import React, { useState } from "react";
import PlacesAutocomplete, {
  geocodeByAddress,
  getLatLng,
} from "react-places-autocomplete";
import CreatableSelect from "react-select/creatable";
import PriceInput from "./PriceInput";

const FormComponent = ({ setModalIsOpen }) => {
  const [name, setName] = useState("Menya");
  const [address, setAddress] = useState(
    "437-439 Elizabeth St, Melbourne VIC 3000"
  );

  const [selectedTags, setSelectedTags] = useState([]);
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedEthnicity, setSelectedEthnicity] = useState("");

  // Predefined price options
  const priceOptions = [
    { value: "$", label: "$" },
    { value: "$$", label: "$$" },
    { value: "$$$", label: "$$$" },
    { value: "$$$$", label: "$$$$" },
    { value: "$$$$$", label: "$$$$$" },
  ];

  // Predefined category options
  const tagOptions = [
    { value: "bar", label: "Bar" },
    { value: "dinner", label: "Dinner" },
    { value: "brunch", label: "Brunch" },
    { value: "cafe", label: "Cafe" },
    { value: "desert", label: "Desert" },
  ];

  // Predefined category options
  const ethnicityOptions = [
    { value: "korean", label: "Korean" },
    { value: "japanese", label: "Japanese" },
    { value: "chinese", label: "Chinese" },
    { value: "italian", label: "Italian" },
    { value: "french", label: "French" },
  ];

  // Handles the submission of the form
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (name && address && selectedPrice && selectedEthnicity) {
      try {
        let cuisine = selectedEthnicity.value;
        let price = selectedPrice.value;
        let tags = selectedTags.map((tag) => tag.value);
        // Log the form input values
        console.log(name);
        console.log(address);
        console.log(selectedPrice);
        console.log(selectedEthnicity);
        console.log(selectedTags);

        // Obtain coordinates & postcode from address
        const geocode = await geocodeAddress(address); // Await the geocodeAddress function
        console.log(geocode); // Log the geocode data
        const longt = geocode.longt;
        const latt = geocode.latt;
        const postcode = geocode.standard.postal;

        // Create data object
        const data = {
          poi_name: name,
          poi_address: address,
          poi_long: longt,
          poi_lat: latt,
          poi_suburb: postcode,
          poi_price: price,
          poi_cuisine: cuisine,
          poi_tags: tags,
        };

        console.log(JSON.stringify(data));

        // Add to database
        const url = "https://dates-fd71bc03469b.herokuapp.com/add_poi";
        const response = await fetch(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(data),
        });

        const pois = await response.json();
        console.log(pois);

        // Reset form fields
        setModalIsOpen(false);     
        // setName("");
        // setAddress("");
        // setSelectedPrice("");
        // setSelectedEthnicity("");
        // setSelectedTags([]);

        return pois;
      } catch (error) {
        console.error("Error fetching data:", error);
      }
    }
  };

  // Handle category selection change
  const handleCategoryChange = (selectedOptions) => {
    setSelectedTags(selectedOptions);
  };

  // Handle price range selection
  const handlePriceRangeSelect = (selectedPrice) => {
    setSelectedPrice(selectedPrice);
  };

  // Handle price range selection
  const handleEthnicitySelection = (selectedEthnicity) => {
    setSelectedEthnicity(selectedEthnicity);
  };

  return (
    <div>
      {/* Show the form which calls handleSubmit when submitted */}
      <form onSubmit={handleSubmit}>
        {/* Show the input for the name */}
        <div>
          <label>Name:</label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
        </div>
        <br />
        {/* Show the input for the address */}
        <div>
          <label>Address:</label>
          <input
            type="text"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            required
          />
        </div>

        <br />

        {/* Show the tag options and ability to create a new one */}
        <div>
          <CreatableSelect
            isMulti
            options={tagOptions}
            value={selectedTags}
            onChange={handleCategoryChange}
            placeholder="Select or create categories..."
            formatCreateLabel={(inputValue) => `Create "${inputValue}" Tag`}
            styles={{
              option: (provided, state) => ({
                ...provided,
                color: "black", // Change this to your desired color
              }),
            }}
          />
        </div>

        <br />

        {/* Select Price */}
        <div className="app-container">
          <PriceInput
            options={priceOptions}
            selectedOption={selectedPrice}
            handleChange={handlePriceRangeSelect}
            placeholder="Select a price range..."
          />
        </div>

        <br />

        {/* Select Ethnicity  */}
        <div className="app-container">
          <PriceInput
            options={ethnicityOptions}
            selectedOption={selectedEthnicity}
            handleChange={handleEthnicitySelection}
            placeholder="Select a cuisine..."
          />
        </div>

        <br />

        {/* Show the submit button */}
        <button type="submit">Add POI</button>
        <br />
      </form>
    </div>
  );
};

async function geocodeAddress(address) {
  // Convert address into a URL-friendly format and create the API URL call
  const API_KEY = "357799306236162781103x104895";
  const apiUrl = `https://geocode.xyz/?locate=${encodeURIComponent(
    address
  )}&json=1&region=AU&auth=${API_KEY}`;

  try {
    // Perform API Call using fetch() method
    const response = await fetch(apiUrl);
    if (!response.ok) {
      throw new Error("API request failed");
    }
    const data = await response.json();
    // Process and return the response data here
    return data; // Return the data so it can be used outside this function
  } catch (error) {
    console.error("Geocode API call failed:", error);
    return null; // Return null or handle the error as needed
  }
}

export default FormComponent;
