import React, { useState, useEffect } from "react";
import FormComponent from "../components/FormComponent";
import Modal from "react-modal";

import "../css/dates.css";
import styles from "../css/dates.css";
import MapComponent from "../components/MapComponent";
import CardComponent from "../components/CardComponent";

import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";

// Set the app element
Modal.setAppElement("#root");

export default function Home() {
  // State variables
  const [testData, setTestData] = useState(null);
  const [pointsOfInterest, setPointsOfInterest] = useState([]);
  const [modalIsOpen, setModalIsOpen] = useState(false);

  const [cards, setCards] = useState([]);

  useEffect(() => {
    const fetchCards = async () => {
      const data = await retrieveData();
      if (data) {
        setCards(data.map(item => displayCard(item)));
      }
    };
    fetchCards();
  }, []);
  

  // Function to test the backend
  const retrieveData = async () => {
    let url = "https://dates-fd71bc03469b.herokuapp.com/get_poi";
    try {
      const response = await fetch(url, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });
      const pois = await response.json();
      // console.log(pois);
      // setTestData(pois);
      return pois;
    } catch (error) {
      console.error("Error fetching data:", error);
    }
  };

  const displayCard = (data) => {
    console.log(data);
    // Capitalise the first letter of the cuisine
    let capCuisine = data.cuisine.charAt(0).toUpperCase() + data.cuisine.slice(1)
    return (
      <CardComponent 
        key={data.id} 
        name={data.name} 
        address={data.address} 
        price={data.price} 
        tags={data.tags} 
        cuisine={capCuisine} />
    );
  }

  return (
    <div className="App">
      <h1>My Leaflet Map</h1>
      {/* Map */}
      <MapComponent
        pointsOfInterest={pointsOfInterest}
        className={styles.map}
      />
      
      {/* Modal */}
      <Modal
        isOpen={modalIsOpen}
        onRequestClose={() => setModalIsOpen(false)}
        style={{
          overlay: {
            zIndex: 2, // Add this line to set the zIndex for the overlay
          },
          content: {
            zIndex: 2, // Add this line to set the zIndex for the modal content
          },
        }}
      >
        <h2>Add a new Point of Interest</h2>
        <FormComponent setModalIsOpen={setModalIsOpen} />
        <br />
        <button onClick={() => setModalIsOpen(false)}>Close</button>
      </Modal>
      <button onClick={() => setModalIsOpen(true)}>Add POI</button>

      {/* TEST */}
      <div className="background-img"></div>
      <div className="line left-line"></div>
      <div className="line right-line"></div>
      <div id="header-hero">
        <section className="hero">
          <div className="hero-content">
            <h1>Discover a Culinary Journey</h1>
            <p>Experience the essence of Japanese cuisine at Wakuda</p>
            <a href="#header-hero" className="cta-button">
              Book a Table
            </a>
          </div>
        </section>
      </div>
      <section className="about-section">
        <div className="about-content">
          <h2>About Us</h2>
          { cards }
          {/* Button to test backend
          <button onClick={retrieveData}>Test Backend</button>

          Display fetched data
          {testData && (
            <div>
              <h2>Test Data</h2>
              <pre>{JSON.stringify(testData, null, 2)}</pre>
            </div> */}
          {/* )} */}
        </div>
      </section>
      <footer className="footer">
        <p>&copy; 2024 Aaron Tran</p>
      </footer>
    </div>
  );
}

