import React from "react";
import '../css/card.css';

const CardComponent = ({ name, address, price, tags, cuisine }) => {
  
  // Function to generate dollar signs
  const generateDollarSigns = (price) => {
    // Get the length of the price, if it exists, otherwise set it to 0
    const priceLength = price ? price.toString().length : 0;
    // Create an array and fill it with the dollar sign icon based on the length of the price
    return Array(priceLength).fill().map((_, i) => (
      <i key={i} className="fa-solid fa-dollar-sign"></i>
    ));
  };

  // Function to generate tags
  const generateTags = (tags) => {
    return (
      tags.map((tag, index) => (
      <li key={index}>{tag}</li>
      ))
    )
  };
      
  return (
    <div id="container">	
      
      <div className="product-details">
        <h1>{name}</h1>
        <br />
        <span className="hint-star star">
          {generateDollarSigns(price)}
        </span>
        <br />
        <br />
        {/* <p className="information"></p> */}
        <div className="ethnicity-information">
          <p>{cuisine}</p>
        </div>
        
        
        <div className="control">
          <button className="btn"></button>
        </div>
      </div>
      
      <div className="product-image">
        <img src="/images/dates/card_background.png" alt="" />frontend
        <div className="info">
          <br />
          <ul>
            <li className="center no-bullet"><strong>Address</strong></li>
            <li className="no-bullet">{address}</li>
            <br />
            <li className="center no-bullet"><strong>Tags</strong></li>
            {generateTags(tags)}
          </ul>
        </div>
      </div>
    </div>
  );
}

export default CardComponent;