import '../css/home.css';
import laptop_icon from '../images/laptop-icon.png';
import potrait from '../images/portrait.jpg';
import linkedin_icon from '../images/linkedin.png';
import github_icon from '../images/github.png';
import instagram_icon from '../images/instagram.png';
import React, { useEffect } from 'react';



export default function Home() {
    useEffect(() => {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('show');
                } else {
                    entry.target.classList.remove('show');
                }
            });
        });

        const hiddenElements = document.querySelectorAll('.hidden');
        hiddenElements.forEach((el) => observer.observe(el));

        return () => {
            hiddenElements.forEach((el) => observer.unobserve(el));
        };
    }, []); // Run once when the component mounts

    return (
        <div>
            {/* <a id="hero" class="anchor"></a> */}
            <div id="section-hero" className="section-body">
                <img src={laptop_icon}/>
                <h2 id="aaron" className="title">Aaron Tran</h2>
                <h4 id="education">4th Year Software Engineer/Commerce Student</h4>
            </div>
            <div id="section-about" className="section-body">
                <h2 className="title hidden">About Me</h2>
                <div className="container">
                    <div className="row">
                        <div className="col-6">
                            <p id="about-text" className="hidden">
                                <br /><br />
                                I'm a high-achieving fourth-year Software Engineering/Commerce Student 
                                at Monash University with professional experience.
                                <br />
                                <br />
                                My coding journey started off from making simple scripts in games and now I 
                                enjoy challenging myself to gain knowledge in various areas. Currently exploring 
                                the field of machine learning and devloping my skills in full-stack development.
                            </p>
                        </div>
                        <div className="col-6 py-5 px-5">
                            <img src={potrait} className="circle hidden" height='300' id="portrait" />
                        </div>
                    </div>
                    <div className="row">
                        <div className="col-7"></div>
                        <div className="col-4 d-flex justify-content-center">
                            <div className="social-logo hidden">
                                <a href="https://www.linkedin.com/in/aarrrontran/" target="_blank">
                                    <img src={linkedin_icon} height='40' className="px-3" />
                                </a>
                            </div>
                            <div className="social-logo hidden">
                                <a href="https://github.com/aarrroon" target="_blank">
                                    <img src={github_icon} height='40' className="px-3" />
                                </a>
                            </div>
                            <div className="social-logo hidden">
                                <a href="https://www.instagram.com/aaronntran/" target="_blank">
                                    <img src={instagram_icon} height='40' className="px-3" />
                                </a>
                            </div>
                        </div>
                        <div className="col-1"></div>
                    </div>
                </div>
            </div>
            <div id="section-skills" className="section-body">
                <h2 className="title hidden">Technical Skills</h2>
                <div className="container">
                    <div className="row">
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="cardr1">
                                <div className="card" id="html">
                                    <img src="images/html.png" />
                                    <h5>HTML 5</h5>
                                </div>
                            </div>
                        </div>
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="cardr1">
                                <div className="card" id="css">
                                    <img src="images/css.png" />
                                    <h5>CSS 3</h5>
                                </div>
                            </div>

                        </div>
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="cardr1">
                                <div className="card" id="js">
                                    <img src="images/js.png" />
                                    <h5>JavaScript</h5>
                                </div>
                            </div>
                        </div>
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="cardr1">
                                <div className="card" id="java">
                                    <img src="images/javalogo.png" height="120px" />
                                    <h5>Java</h5>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="row">
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="card cardr2" id="python">
                                <img src="images/python.png" />
                                <h5>Python 3</h5>
                            </div>
                        </div>
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="hidden cardr2">
                                <div className="card cardr2" id="git">
                                    <img src="images/git.png" />
                                    <h5>Git</h5>
                                </div>
                            </div>
                        </div>
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="card cardr2" id="react">
                                <img src="images/react.png" />
                                <h5>React</h5>
                            </div>
                        </div>
                        <div className="col d-flex justify-content-center py-3 hidden scard">
                            <div className="hidden cardr2">
                                <div className="card cardr2" id="bootstrap">
                                    <img src="images/bootstrap.png" />
                                    <h5>Bootstrap</h5>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}